      "attacks": [
        {
          "id": "k1kPrQ3Krhcipl4E",
          "name": "Fist",
          "bonus": 20,
          "damage": "2d10+7 bludgeoning",
          "traits": [
            "magical",
            "reach-10",
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "95kvqPPSJNio8vAK",
          "name": "Berserk",
          "kind": "passive",
          "description": "A severely damaged flesh golem has a chance of going berserk. If it has 40 or fewer HP at the start of its turn, the golem must succeed at a check (flat, dc:5) check or go berserk. A berserk golem wildly attacks the nearest living creature, or the nearest object if no creatures are nearby.",
          "traits": []
        },
        {
          "id": "Hss992fc1sCOcDVo",
          "name": "Electric Reflexes",
          "kind": "reaction",
          "description": "Trigger The golem takes electricity damage and a creature is adjacent to it.\nEffect The golem lashes out and tries to grab a nearby creature. The golem attempts an Athletics check to Grapple an adjacent creature. The creature also takes 3d6 electricity damage on a success, or 6d6 electricity damage on a critical success.",
          "traits": []
        },
        {
          "id": "WQED2R71AMrx1suT",
          "name": "Golem Antimagic",
          "kind": "passive",
          "description": "Harmed by fire 5d8 untyped damage, 3d4 untyped damage from areas or persistent damage); healed by electricity (area 2d4 healing HP); slowed by cold",
          "traits": []
        },
        {
          "id": "uzwUjI3gD8tO8Chh",
          "name": "Vulnerable to Flesh to Stone",
          "kind": "passive",
          "description": "Casting a Petrify spell on the flesh golem affects the golem normally.",
          "traits": []
        },
        {
          "id": "hvTnI184eIoLfwPq",
          "name": "Berserk Slam",
          "kind": "action",
          "description": "Requirements The flesh golem is berserk.\nEffect The flesh golem Strikes with its fist at a -1 circumstance penalty. If it hits, it deals 1d6 extra damage and knocks the target Prone.",
          "traits": []
        }
      ],
      "spellcasting": []
