      "attacks": [
        {
          "id": "YyBAAbT6VQ7kpDW4",
          "name": "Jaws",
          "bonus": 12,
          "damage": "2d6+8 piercing",
          "traits": [
            "unarmed"
          ]
        },
        {
          "id": "GTW3qSprQnTyrwNU",
          "name": "Claw",
          "bonus": 12,
          "damage": "2d4+8 slashing",
          "traits": [
            "agile",
            "unarmed"
          ]
        }
      ],
      "actions": [
        {
          "id": "nKM6FVNsXbBwEPNq",
          "name": "Gnaw",
          "kind": "action",
          "description": "Requirements The wolverine has a creature Grabbed from its jaws Strike\nEffect The wolverine chews violently on the creature, dealing 2d6 piercing damage (check (fortitude, dc:21, basic) save). A creature that fails its save also takes 2d6 persistent bleed damage.",
          "traits": []
        },
        {
          "id": "YdcYSwBDfJFctOhL",
          "name": "Pounce",
          "kind": "action",
          "description": "The giant wolverine Strides and makes a Strike at the end of that movement. If the giant wolverine begins this action Hidden, it remains hidden until after the attack.",
          "traits": []
        },
        {
          "id": "PKHHueFUrRyFJPxL",
          "name": "Rend",
          "kind": "action",
          "description": "Claw",
          "traits": []
        },
        {
          "id": "jzbdXMuXge2oT2ol",
          "name": "Wolverine Rage",
          "kind": "action",
          "description": "The giant wolverine enters a state of pure rage that lasts either for 1 minute, until there are no enemies it can perceive, or until it falls Unconscious, whichever comes first. While raging, the giant wolverine has AC 20, its jaws Strike deals 2d6+11 damage, and its claw Strike deals 2d4+11 damage. While raging, the giant wolverine can't use actions that have the concentrate trait, except for Seek.\nAfter it's stopped raging, a giant wolverine can't use Wolverine Rage again for 1 minute.",
          "traits": [
            "concentrate"
          ]
        },
        {
          "id": "ubttzSAG6qyejH25",
          "name": "Grab",
          "kind": "action",
          "description": "",
          "traits": []
        }
      ],
