        {
          "id": "xKGmyTmllHIjiYO0",
          "name": "Earth Shaker",
          "kind": "passive",
          "description": "Each turn, the first time the duneshaker solifugid is adjacent to a Large or smaller creature during a move action it's using, that creature must succeed at a check (reflex, dc:39) save or fall Prone.",
          "traits": [
            "move"
          ]
        },
        {
          "id": "qwrA1CcDM9QaJlc5",
          "name": "Pounce",
          "kind": "action",
          "description": "The duneshaker solifugid Strides and makes a Strike at the end of that movement. If the duneshaker solifugid began this action Hidden, it remains hidden until after this ability's Strike.",
          "traits": []
        },
        {
          "id": "KkNlymsNYCYGKgtS",
          "name": "Rend",
          "kind": "action",
          "description": "Claw",
          "traits": []
        },
        {
          "id": "dUfRUEqARe3yHUZM",
          "name": "Venom Spray",
          "kind": "action",
          "description": "The duneshaker solifugid spews toxic barbs at all creatures in a 30-foot cone. Each creature within the area takes 10d6 poison damage (check (fortitude, dc:39, basic, options:area-effect,inflicts:blinded) save). A creature that fails its saving throw is Blinded for 1d6 (or permanently on a critical failure).\nThe duneshaker solifugid can't use Venom Spray again for 1d4.",
          "traits": [
            "poison"
          ]
        }
