        {
          "id": "nszzMLENLPQ4zPoa",
          "name": "Tenacious Flames",
          "kind": "passive",
          "description": "100 feet. Creatures in the emanation cannot recover from persistent fire damage.",
          "traits": [
            "aura",
            "fire",
            "primal"
          ]
        },
        {
          "id": "mY1TZIEvZh0l0OBD",
          "name": "Throw Rock",
          "kind": "action",
          "description": "A lerritan can break stony scales off its body to throw; these scales reform at the end of each round, so the lerritan is never without a supply of rocks to hurl.",
          "traits": []
        },
        {
          "id": "JGXYh66auv2dCHDv",
          "name": "Volcanic Eruption",
          "kind": "action",
          "description": "The volcano on the lerritan's back erupts and sends lava bombs raining down in a 30-foot emanation, dealing 12d12 fire damage.\nEach creature in the area must attempt a check (reflex, dc:46, options:area-effect,damaging-effect,inflicts:encumbered,inflicts:immobilized) saving throw. The lava globules quickly cool into heavy stones, transforming the area into greater difficult terrain for non-lerritans.\nThe lerritan can't use Volcanic Eruption for 1d4.\nCritical Success The creature is unaffected.\nSuccess The creature takes half damage and is Encumbered for 1 round.\nFailure The creature takes full damage and is Immobilized (Escape DC 46).\nCritical Failure The creature takes double damage and is encased in a rocky crust with lava on the inside. The creature is Restrained (Escape DC 46), can't breathe, takes 3d12 persistent fire damage, and can't recover from this persistent fire damage until freed.",
          "traits": [
            "earth",
            "fire",
            "primal"
          ]
        }
